def mark_legacy_positions_unvalued(apps, schema_editor):
    alias = schema_editor.connection.alias
    Movement = apps.get_model('inventory', 'StockMovement')
    Balance = apps.get_model('inventory', 'InventoryValuationBalance')
    positions = Movement.objects.using(alias).values(
        'product_id', 'warehouse_id', 'product__organization_id'
    ).annotate(quantity=Sum('quantity'))
    for position in positions.iterator():
        quantity = position['quantity'] or Decimal('0')
        Balance.objects.using(alias).get_or_create(
            organization_id=position['product__organization_id'],
            product_id=position['product_id'],
            warehouse_id=position['warehouse_id'],
            defaults={
                'quantity_on_hand': quantity,
                'inventory_value': Decimal('0.00'),
                # Old movement costs came from different snapshots and are not a
                # complete weighted-average history. Do not infer their value.
                'is_valued': quantity == 0,
                'valuation_start_date': None,
            },
        )


